  "— her gün sıfırdan dolar, üst üste birikmez.": "— si ricarica da zero ogni giorno, non si accumula.",
  "Sonuçlar": "Risultati",
  "Sonuç": "Risultato",
  "Maç devam ediyor...": "Partita in corso...",
  "Maç, turnuva ve lig sıralama ödülleri": "Premi per partite, tornei e classifiche di campionato",
  "Maç, lig ve turnuva ödülleri otomatik olarak": "I premi di partite, campionato e tornei vengono automaticamente",
  "ödenir. Ödeme günleri: sezonun": "pagati. Giorni di pagamento della stagione:",
  "Antrenman, seçtiğin yeteneğe": "L'allenamento assegna all'abilità che scegli",
  "kazandırır; yetenek seviyen yükseldikçe oyuncu gücün (OVR) artar.": "in più; man mano che il livello dell'abilità sale, la forza del giocatore (OVR) aumenta.",
  ". İstediğin gruptan çalışabilirsin.": ". Puoi allenarti in qualsiasi gruppo.",
  ". Farklı gruba (Kaleci / Defans / Orta Saha / Forvet) geçişte": ". Passando a un altro gruppo (Portiere / Difesa / Centrocampo / Attacco)",
  "ve o grubun yeni yetenekleri 10'dan başlar.": "e le nuove abilità di quel gruppo partono da 10.",
  "eşittir (Sv.1 → 1 eş zamanlı).": "è pari (Liv.1 → 1 simultaneo).",
  "ile başlarsın. Takım tesisin (Performans Merkezi) her seviye için": "per iniziare. La struttura della tua squadra (Centro prestazioni) aggiunge per ogni livello",
  "harcama; hangisi önce dolarsa orada durur.": "di spesa; ci si ferma al primo limite raggiunto.",
  "işlenir, her bilet denetim için kaydedilir.": "viene elaborato e ogni biglietto è registrato per i controlli.",
  "kazanır. Elmas ortalama her 200 bilette bir çıkar.": "vince. In media esce un diamante ogni 200 biglietti.",
  "'de sıfırlanır. Kazanç tavanı Toto ile ortaktır.": ". Il tetto delle vincite è condiviso con il Toto.",
  "Ücretsiz günlük bilet 25'e sayılmaz. Tüm sayaçlar": "Il biglietto giornaliero gratuito non conta nei 25. Tutti i contatori si azzerano alle",
  "güncel sezon maaşı ÷ 4": "stipendio stagionale attuale ÷ 4",
  "ve talep ettiğin": "e quanto richiesto",
  "(final galibi) ayrıca": "(il vincitore della finale) inoltre",
  "de buluşur. Final hariç tüm turlar çift maçlıdır.": "si incontrano. Tutti i turni tranne la finale sono ad andata e ritorno.",
  ". Lig sonunda hak kazanan takımlar turnuvalara katılır.": ". Le squadre qualificate a fine campionato partecipano ai tornei.",
  "olarak katılacaksın. İstediğin zaman ayrılabilirsin.": "sarà il tuo ruolo. Puoi andartene quando vuoi.",
  ". Diğer üyeler oylarını veriyor.": ". Gli altri membri stanno votando.",
  ". Sonraki seçimde tekrar başvurabilirsin.": ". Potrai candidarti di nuovo alle prossime elezioni.",
  "Karşı takım kaptanı kabul ederse maç planlanır.": "La partita viene programmata se il capitano avversario accetta.",
  "(Sahadan çıkarmak için diziliş ekranında yedeğe sürükleyin.)": "(Per togliere un giocatore dal campo, trascinalo in panchina nella schermata formazione.)",
  ". Tüm takımlar, oyuncular ve maçlar kurgusaldır.": ". Tutte le squadre, i giocatori e le partite sono immaginari.",
  ". Katılım yalnızca oyun içi sanal para ile yapılır;": ". La partecipazione avviene solo con valuta virtuale di gioco;",
  ", kazanılan ödüller yalnızca oyun içinde kullanılır ve": ", i premi vinti sono utilizzabili solo nel gioco e",
  ", oyuncunun yeteneklerinin ortalamasıdır ve": ", è la media delle abilità del giocatore e",
