  "Bir takıma katıl veya kendi takımını kur. Takımsız oyuncu olarak antrenman, lig ve turnuva izleme erişimin var.": "Unisciti a una squadra o fondane una tua. Da svincolato hai comunque accesso all’allenamento e alla visione di campionati e tornei.",
