  "Bu ülkede takım sahibi olan tüm kaptanlar otomatik olarak federasyon üyesidir. Sezon sonu seçimde her üyenin": "Tutti i capitani proprietari di una squadra in questo Paese sono automaticamente membri della federazione. Nell’elezione di fine stagione ogni membro ha",
