  "🏆 Pro görevler oyunun en büyük zaferleri — şampiyonluklar ve milli takım. Tek seferlik, kalıcı.": "🏆 Le missioni Pro sono le imprese più grandi del gioco — titoli e Nazionale. Una tantum e permanenti.",
