  "Yüksek seviyeli antrenmanlar daha çok enerji harcar — verimli puan demek.": "Gli allenamenti di livello più alto costano più energia — cioè punti più efficienti.",
  "Kadronu kontrol et, akıllı kadro öner butonuyla en iyi 11'i hızlıca diz!": "Controlla la rosa — usa il pulsante rosa intelligente per schierare i migliori 11 in fretta!",
  "Sahadaki oyuncuya dokun → yedeklerden birini seç. Sürüklemek için karta": "Tocca un giocatore in campo → scegli qualcuno dalla panchina. Per trascinare, sulla carta",
