  "Hazırlıklarını yap. Strateji ve kadro ayarlarını gözden geçir.": "Preparati. Rivedi strategia e impostazioni della rosa.",
  "Bir sonraki sezon hazırlıkları için kadronu yeniden şekillendirme zamanı.": "È ora di rimodellare la rosa per la prossima stagione.",
  "kadronu güçlendirmek, sakat veya formdan düşen oyuncularını değiştirmek için": "per rinforzare la rosa e sostituire i giocatori infortunati o fuori forma",
  "• Bitkin oyuncular maçta düşük performans gösterir ve sakatlanma riski artar.": "• I giocatori esausti rendono poco in partita e rischiano di più l'infortunio.",
