  "• Antrenmana devam ederek daha da yükselebilirsin.": "• Continua ad allenarti per salire ancora di più.",
  "yenilenir; oyuna girsen de girmesen de sunucu yeniler.": "si ricarica; il server la ricarica che tu acceda o no.",
