  "Bir hafta boyunca oynadığın tüm maçların reytinglerinin": "Dei voti di tutte le partite che giochi in una settimana,",
  "alan oyuncular yarışır. Maç motoru her maçta oyuncularının performansını 17 farklı kategoride değerlendirir ve bir maç sonu reytingi üretir.": "giocatori si sfidano. Il motore di gioco valuta la prestazione di ogni giocatore in 17 categorie e produce un voto finale.",
  "oyuncular yarışır. Antrenman seansı yaptığında harcadığın enerji bu yarışın puanına eklenir.": "giocatori si sfidano. L'energia che spendi negli allenamenti conta per questa sfida.",
  "Ödülünü ödül penceresi içinde toplamazsan iptal olur. Yeni yarış başladıktan sonra eski ödüller kaybolur.": "Se non riscuoti il premio entro la finestra dei premi, viene annullato. I vecchi premi si perdono quando inizia una nuova sfida.",
  "✅ Bu serideki tüm hediyelerini topladın. Yarın da gir, seri devam etsin!": "✅ Hai raccolto tutti i regali di questa serie. Accedi anche domani per continuarla!",
  "🚪 Her gün giriş yap, serini büyüt! İlk gün hediyesi seni bekliyor.": "🚪 Accedi ogni giorno per allungare la serie! Il regalo del primo giorno ti aspetta.",
  "toplanmamış hediyen var! Toplamadan gün kaçırırsan yanar.": "regali non riscossi! Se salti un giorno senza riscuoterli, scadono.",
  "Bir takıma katılıp maç oynadığında buraya yansıyacak.": "Si riempirà quando entrerai in una squadra e giocherai partite.",
  "Takım Puanı her resmi maç sonucunun kademe çarpanıyla hesaplanır (Takımlar sekmesindeki bilgi kutusuyla aynı çarpanlar).": "I Punti squadra si calcolano da ogni risultato ufficiale con il moltiplicatore di divisione (gli stessi moltiplicatori del riquadro info nella scheda Squadre).",
  "maç sonucu, oynanan kademenin çarpanıyla puana çevrilip toplanır. Hazırlık ve milli maçlar sayılmaz.": "risultati delle partite vengono convertiti in punti con il moltiplicatore della divisione e sommati. Amichevoli e partite delle nazionali non contano.",
  "takımlar arasında gerçek küresel sıradır.": "è la vera classifica globale tra le squadre.",
  "katkısı sayılır; 6. sezon başlayınca en eski sezon düşer. Her sezonun katkısı satırdaki kartlarda ayrı görünür.": "conta; all'inizio della stagione 6 la stagione più vecchia esce dal conteggio. Il contributo di ogni stagione appare separato nelle card della riga.",
  "her ülkenin Süper Lig'inde 1-6. sıralar belirlenir": "i posti 1–6 si decidono nella Superlega di ogni paese",
  "bir önceki sezonun final puan tablosundan": "dalla classifica finale della stagione precedente",
  "sonu sıralamasından · Play-Off'a gidecek takımlar": "classifica finale · squadre dirette al Play-Off",
  "En iyi 50 oyuncu listelenir; kendi oyuncun listede yoksa en altta gerçek sıranla görünür.": "Sono elencati i migliori 50 giocatori; se il tuo non c'è, appare in fondo con la sua posizione reale.",
  "kralı listesi sezonun ilerleyen günlerinde görünecek.": "classifica apparirà più avanti nella stagione.",
