  "📅 Turnuva istatistikleri sezon ilerledikçe burada görünecek": "📅 Le statistiche del torneo appariranno qui con l'avanzare della stagione",
  "📅 Sezon henüz başlamadı veya yeterince ilerlemedi —": "📅 La stagione non è ancora iniziata o non è abbastanza avanzata —",
  "Sözleşmesiz: oyuncu istediği zaman ayrılır. Sözleşmeli: süre (1-5 sezon) bitene dek ayrılamaz. İkisinde de oyuncu sistem maaşını alır.": "Senza contratto il giocatore può andarsene quando vuole. Con contratto non può andarsene fino alla scadenza (1-5 stagioni). In entrambi i casi riceve lo stipendio di sistema.",
  "oyuncu. Bonservis yok, sadece maaş + opsiyonel imza elması.": "giocatore. Nessun costo di trasferimento — solo lo stipendio più eventuali diamanti alla firma.",
  "düşer. Maaş, ödeme günlerinde yatar; ilk ödeme katıldığı günden itibaren orantılıdır.": "scende. Gli stipendi si pagano nei giorni di paga; il primo pagamento è proporzionale dal giorno di ingresso.",
  "kasasına aktarılır. Maaş 4 taksit halinde (gün 10/20/30/40) sezonun her çeyreğinde ödenir.": "viene versato in cassa. Lo stipendio è pagato in 4 rate (giorni 10/20/30/40), una per ogni quarto di stagione.",
  "Sistem belirledi · kulüp kasasına yatar, cüzdana değil": "Stabilito dal sistema · versato nella cassa del club, non nel portafoglio",
  "ilk maaşa düşer + ayrılma serbestliği kazanır": "scende al primo stipendio + ottiene la libertà di andarsene",
  ") + takımdan ayrılma serbestliği kazanırsın.": ") + ottieni la libertà di lasciare la squadra.",
  ") düşer + takımdan ayrılma serbestliği kazanırsın.": ") scende + ottieni la libertà di lasciare la squadra.",
  "Bu durumlardan biri gerçekleşene kadar takımda kalman gerekir.": "Devi restare in squadra finché non accade una di queste cose.",
  "🔓 Sözleşmen sona erdi — İstediğin an ayrılabilirsin": "🔓 Il tuo contratto è scaduto — puoi andartene quando vuoi",
  "• Sözleşme: 1 sezon (sezon sonu yenileme talebi ile uzar)": "• Contratto: 1 stagione (si estende con una richiesta di rinnovo a fine stagione)",
  "📨 Talep göndereceksin. Kaptan onaylarsa yeni maaş aktif olur.": "📨 Invierai una richiesta. Se il capitano approva, il nuovo stipendio entra in vigore.",
  "Farklı şartlarla yeni bir istek gönderebilir veya başka takımlara başvurabilirsin.": "Puoi inviare una nuova richiesta con altre condizioni o candidarti ad altre squadre.",
  "⚠️ Yenileme reddedildi — Maaşın eski seviyeye düştü": "⚠️ Rinnovo rifiutato — il tuo stipendio è tornato al livello precedente",
  "Bu oyuncu başka bir takımla sözleşmeli — sözleşmeli transfer sadece transfer günlerinde yapılabilir (ara: 16-18. gün, sezon arası: 34-40. gün). Sonraki dönem:": "Questo giocatore ha un contratto con un'altra squadra — i trasferimenti di giocatori sotto contratto sono possibili solo nei giorni di mercato (metà stagione: giorni 16-18, pausa stagionale: giorni 34-40). Prossima finestra:",
  "işlemi sadece transfer dönemlerinde yapılabilir": "è possibile solo durante le finestre di trasferimento",
  "Lig sezonu sona erdi. Bu dönemde sezon sonu transfer pazarı açılır ve": "La stagione di campionato è terminata. In questo periodo apre il mercato di fine stagione e",
