  ") varken yeni takım satın alırsan, eski takımın senden ayrılır.": ") — se compri una nuova squadra, perderai quella vecchia.",
  "💡 Bu takımın kaptanı kadrosunu büyütmediği için yeni istek kabul edilemez. Başka bir takım dene veya bekle.": "💡 Il capitano di questa squadra non ha ampliato la rosa, quindi non si accettano nuove richieste. Prova un'altra squadra o attendi.",
  "takımına katıldın (sözleşmesiz — istediğin zaman ayrılabilirsin).": "sei entrato in squadra — senza contratto, puoi andartene quando vuoi.",
  "takımına zaten istek gönderdin (beklemede).": "hai già inviato una richiesta a questa squadra (in attesa).",
