  "transfer pazarından geri alınacak ve takımında kalmaya devam edecek.": "verrà ritirato dal mercato trasferimenti e resterà nella tua squadra.",
  "ile olan tüm konuşma silinecek. Bu işlem geri alınamaz.": "l'intera conversazione verrà eliminata. L'operazione non può essere annullata.",
  "Seçimler her sezonun 1–3. günleri arasında yapılır; sonuçlar 3. gün 19:00'da açıklanır.": "Le elezioni si tengono nei giorni 1–3 di ogni stagione; i risultati sono annunciati il giorno 3 alle 19:00.",
  "Tüm üyeler istediği zaman aday olabilir; en yüksek 5 etki kullanıcıya bonus aday olur": "Ogni membro può candidarsi quando vuole; i 5 utenti con più influenza diventano candidati bonus",
  "En çok oyu alan başkan, 2-3-4. sıra yardımcı olur": "Il più votato diventa presidente; 2º, 3º e 4º diventano vicepresidenti",
