  "federasyon seçiminde kime oy verdiğin hiç kimseye gösterilmez.": "chi hai votato in un'elezione della federazione non viene mai mostrato a nessuno.",
  "Bu federasyonun üyesi değilsin (izleyici modu). Aday olamaz veya oy veremezsin.": "Non sei membro di questa federazione (modalità spettatore). Non puoi candidarti né votare.",
