  "Federasyon Yetkiler sekmesinden detayları görebilirsin.": "Puoi vedere i dettagli nella scheda Permessi della Federazione.",
  "Davet zorunludur, oyuncunun onayı gerekmez.": "La convocazione è obbligatoria; non serve il consenso del giocatore.",
  "milli takım kadrosuna alınacak ve oyuncuya bilgilendirme mesajı gönderilecek.": "verrà convocato in Nazionale e il giocatore sarà avvisato.",
  "milli takımdan çıkarılacak. Boşalan slot için Analiz sekmesinden yeni bir oyuncu davet etmeyi unutma.": "verrà escluso dalla Nazionale. Ricordati di convocare un sostituto dalla scheda Analisi.",
  "milli takımdan çıkarılacak. Boşalan slot için yeni bir oyuncu davet etmeyi unutma.": "verrà escluso dalla Nazionale. Ricordati di convocare un sostituto.",
  "Oyuncu hâlâ milli takım havuzunda kalır, daha sonra geri alabilirsin.": "Il giocatore resta nel gruppo della Nazionale; potrai richiamarlo più tardi.",
  "Milli takımla kazanacağın ilk kupa burada görünecek. Önce kadroya davet edilmen, sonra eleme grubunu geçmen gerekir.": "Il tuo primo trofeo con la Nazionale apparirà qui. Prima devi essere convocato, poi superare il girone di qualificazione.",
  "Milli takım fikstürü sezon başında oluşturulur.": "Il calendario della Nazionale viene creato a inizio stagione.",
  "Sadece milli takım prestiji ve oyuncu istatistikleri.": "Solo prestigio della Nazionale e statistiche dei giocatori.",
  "Lig fikstürü sezon başında oluşturulacak.": "Il calendario del campionato verrà creato a inizio stagione.",
  "Fikstürler oluştuğunda Toto bültenleri otomatik açılacak.": "I palinsesti Toto si apriranno automaticamente una volta creato il calendario.",
  "Turnuva fikstürü \"Turnuvalar\" menüsünde görüntülenebilir.": "Il calendario del torneo è visibile nel menu \"Tornei\".",
