  "Takımlar belirlendiğinde burada listelenecek": "Le squadre saranno elencate qui una volta decise",
  "EURO Cup kurası henüz çekilmedi — fikstür belli olunca burada görünür.": "Il sorteggio della EURO Cup non è ancora stato effettuato — il calendario apparirà qui una volta definito.",
