  "PO1 maçları tamamlandığında burada listelenecek.": "Saranno elencate qui al termine delle partite del PO1.",
  "PO1'den düşenler · Kazanan Grup Aşamasına geçer": "Perdenti del PO1 · la vincente accede alla Fase a gironi",
  "· Her ligin 1.si diğer ligin 2.siyle eşleşir · Kazanan Grup Aşamasına geçer": "· La 1ª di ogni campionato affronta la 2ª dell'altro · la vincente accede alla Fase a gironi",
