  "Bugün için hiçbir lige veya turnuvaya kupon yatırılmamış. İlk kuponu sen yatırırsan havuzu sen başlatırsın.": "Oggi nessuna schedina è stata giocata su alcun campionato o torneo. Gioca la prima schedina e avvierai tu il montepremi.",
  "Ev sahibi maçlarda bilet geliri sağlayan taraftar kapasitesi. Süper Lig'de €25/bilet, alt liglerde daha az.": "Capienza di tifosi che genera incassi dai biglietti nelle partite in casa. €25/biglietto in Superlega, meno nelle divisioni inferiori.",
